from pathlib import Path
import json,re,textwrap
R=Path(__file__).resolve().parents[2];S=R/'baseline/source';O=R/'battles/early'
entries=[]
def add(mapname,label,trainer,reason,paras):
 p=f'data/maps/{mapname}/scripts.inc';txt=(S/p).read_text();m=re.search(r'^'+re.escape(label)+r':\n(?P<body>(?:\s*\.string.*\n)+)',txt,re.M);assert m,label
 raw=m['body'];line=txt[:m.start()].count('\n')+1
 entries.append({'source':p,'label':label,'line':line,'trainer':trainer,'decision':'REPAIR','current_native':raw.rstrip(),'assessment':reason,'final_paragraphs':paras,'final_native':'\n'.join('\t.string "'+z.replace('"','\\"')+end+'"' for pi,para in enumerate(paras) for j,z in enumerate(textwrap.wrap(para,width=34,break_long_words=False,break_on_hyphens=False)) for end in [('\\n' if j<len(textwrap.wrap(para,width=34,break_long_words=False,break_on_hyphens=False))-1 else ('$' if pi==len(paras)-1 else '\\p'))]),'acceptance':'Implement only this label and retain its callers/flags/rewards. Render every page with the actual font and tokens; verify no overflow, correct badge/state transitions, and identical dialogue after materially different valid winning strategies.'})
a=lambda label,tr,reason,p:add('RustboroCity_Gym','RustboroCity_Gym_Text_'+label,tr,reason,p)
a('JoshIntro','TRAINER_JOSH','Sturdy is conditional on full HP and can be bypassed; the current guarantee is false.',['BONSLY and SHIELDON can survive a knockout blow at full health.','We make that extra action count!'])
a('JoshPostBattle','TRAINER_JOSH','Roxanne now has Sturdy Nosepass, but even then Sturdy is not an unconditional extra turn.',['STURDY can preserve NOSEPASS at full health. Chip damage or an Ability that bypasses it changes the plan.'])
a('MarcIntro','TRAINER_MARC','Weather replacement after Veil is set does not remove the established screen.',['AMAURA calls snow and raises AURORA VEIL.','Stop the screen or find a way through!'])
a('GuideIntroduction','TRAINER_ROXANNE_1','Preserve teacher character while describing every team as a serious doubles contest, not staged beginner instruction.',['Yo! Welcome to RUSTBORO GYM.','Every trainer here brings a complete doubles plan. ROXANNE brings the full force of her Rock team.','Prepare your partners, study the board, and make your own opening.','Take these FRESH WATERS. Come see me after you earn the BADGE!'])
a('GymGuideAdvice','TRAINER_ROXANNE_1','Replace broad type-only guidance with truthful optional advice supporting several solutions.',['ROXANNE uses Rock Pokémon with different jobs.','CARBINK can reverse move order with TRICK ROOM. NOSEPASS can guard its partner from spread attacks.','Water and Grass are useful, but target choice and timing still matter. Build the answer that suits your team!'])
a('RoxanneIntro','TRAINER_ROXANNE_1','The final team has Wide Guard rather than an attack-redirecting ability; keep the teacher identity and strong challenge.',['I am ROXANNE, RUSTBORO\'s GYM LEADER.','Each challenger gives me something new to study.','My Pokémon can endure a blow, guard a partner, or reverse the order of battle.','Show me how your team answers mine.'])
a=lambda label,tr,reason,p:add('DewfordTown_Gym','DewfordTown_Gym_Text_'+label,tr,reason,p)
a('GymGuideAdvice','TRAINER_BRAWLY_1','Do not rule out all Normal support choices; explain actual redirection and priority while preserving the lighting cue.',['BRAWLY brings a powerful Fighting team, but his partners do more than attack.','PACHIRISU draws single-target moves aside. His fighters use speed, priority and support to create openings.','Normal Pokémon risk Fighting damage, but a useful support role can still earn a place on your team.','The GYM grows brighter as you defeat its trainers. Make every action count!'])
a('TakaoIntro','TRAINER_TAKAO','Shadow Tag/Octolock have escape exceptions; remove an absolute no-exit claim.',['GRAPPLOCT can hold a target in place. WOBBUFFET makes switching difficult too.','Let us see how you handle the pressure!'])
a('TakaoDefeat','TRAINER_TAKAO','The victory may not have involved a critical window.',['You won a tough battle!'])
a('TakaoPostBattle','TRAINER_TAKAO','No rare Dragon exists on this team.',['HITMONLEE\'s WHITE HERB can clear its stat drops and activate UNBURDEN.','Speed can change in the middle of a turn. Watch the whole board.'])
a('JocelynIntro','TRAINER_JOCELYN','Priority tiers and opposing speed control mean Tailwind does not necessarily precede every opposing move.',['TAILWIND can change the race in an instant.','Four turns of pressure. Can your team handle them?'])
a('JocelynDefeat','TRAINER_JOCELYN','Avoid claiming a specific observed pressure-denial solution.',['You took this battle!'])
a('JocelynPostBattle','TRAINER_JOCELYN','No Natu or Magic Bounce exists on Jocelyn\'s current team.',['TAILWIND lasts four turns. BRELOOM\'s POISON HEAL can keep it going while the field changes.','Plan for the partners still in reserve.'])
a('LauraDefeat','TRAINER_LAURA','Winning does not imply both Fake Outs were denied.',['That was a hard-fought win!'])
a('LilithDefeat','TRAINER_LILITH','Avoid asserting a specific complete tactical read.',['You brought a winning team!'])
a('BrendenDefeat','TRAINER_BRENDEN','Avoid asserting the player changed answers.',['We gave it everything!'])
a('CristianDefeat','TRAINER_CRISTIAN','No form change is required or necessarily observed.',['Our formation could not hold!'])
a('CristianPostBattle','TRAINER_CRISTIAN','Riolu/Leek/Throh belong to other teams; reference the actual repaired Beat Up lead.',['FALINKS can power up JUSTIFIED before its partner attacks.','GALLADE and LUCARIO can both use that opening. Always check who is active.'])
a=lambda label,tr,reason,p:add('MauvilleCity_Gym','MauvilleCity_Gym_Text_'+label,tr,reason,p)
a('KirkPostBattle','TRAINER_KIRK','The team is a terrain/ability puzzle, not a sound amplifier roster.',['ELECTRIC TERRAIN protects grounded Pokémon from sleep.','A Flying Pokémon or an AIR BALLOON changes which benefits apply.'])
a('ShawnIntro','TRAINER_SHAWN','Several actual team members are grounded.',['Some of my Pokémon float above Ground attacks. Others use the terrain beneath them.','Can you tell which answer fits each pair?'])
a('ShawnPostBattle','TRAINER_SHAWN','There is no Helping Hand/Electroweb lead in this team.',['BELLIBOLT can set ELECTRIC TERRAIN for RAICHU\'s SURGE SURFER.','MEGA AMPHAROS brings a different pace and a Dragon typing.'])
a('BenPostBattle','TRAINER_BEN','No Oranguru or Trick Room exists.',['CHARJABUG powers special attacks with BATTERY. DISCHARGE can even heal LANTURN.','That same move is not safe beside every partner.'])
a('AngeloIntro','TRAINER_ANGELO','Compound Eyes Thunder is 91 percent under ordinary accuracy conditions, not guaranteed.',['JOLTIK makes THUNDER more reliable, and TOXTRICITY turns sound into power.','We are ready to take our chances!'])
a('AngeloPostBattle','TRAINER_ANGELO','No Vikavolt or Sticky Web exists in Angelo\'s team.',['WATTREL can set TAILWIND, and JOLTIK can slow opponents with ELECTROWEB.','Those moves change speed in different ways.'])
a('WattsonIntro','TRAINER_WATTSON_1','No Trick Room/reverse-order move exists in Wattson\'s actual final team.',['Wahahahah! I am WATTSON!','ELECTRODE sends the current. ELECTIVIRE turns it into speed.','I know how my partners work together. Show me what yours can do!'])
a('WattsonDefeat','TRAINER_WATTSON_1','Memorization is a legitimate part of Retry and this text should not deny that winning method.',['Wahahah! What a battle!','You have earned the DYNAMO BADGE!'])
a=lambda label,tr,reason,p:add('LavaridgeTown_Gym_1F','LavaridgeTown_Gym_1F_Text_'+label,tr,reason,p)
a('GymGuideAdvice','TRAINER_FLANNERY_1','Flannery has neither Trick Room nor Solar Beam in this roster; explain After You and sun accurately.',['FLANNERY\'s sun strengthens Fire attacks and weakens Water attacks.','LILLIGANT can use AFTER YOU to let slow TORKOAL attack sooner.','Weather control, disruption and careful damage all offer different ways to challenge that partnership.'])
a('FlanneryIntro','TRAINER_FLANNERY_1','The claimed two ways of making the slowest member act first refers to removed Room; preserve timing personality.',['I am FLANNERY, LAVARIDGE\'s GYM LEADER!','MT. CHIMNEY taught me that power needs timing.','LILLIGANT and TORKOAL are ready to turn up the heat. Show us your best!'])
a('FlanneryDefeat','TRAINER_FLANNERY_1','No Balloon exists and no winning sequence is mandatory; preserve reward handoff.',['That was a blazing battle!','You beat the team I put my heart into. Take the HEAT BADGE!'])
a=lambda label,tr,reason,p:add('PetalburgCity_Gym','PetalburgCity_Gym_Text_'+label,tr,reason,p)
a('RandallIntro','TRAINER_RANDALL','Use reconciled room name and truthful multihit wording.',['This is the MULTIHIT ROOM.','One attack can strike again and again. A FOCUS SASH may not be enough!'])
a('ParkerIntro','TRAINER_PARKER','Use reconciled room name and describe reverse speed without promising universal order.',['Welcome to the TRICK ROOM.','The slower Pokémon can move first here. ORANGURU can also make its partner repeat an attack.','Let us see how you position your team.'])
a('ParkerDefeat','TRAINER_PARKER','Current team has no confusion move to support the inherited claim.',['Our timing was not enough. Good battle!'])
a('GeorgeIntro','TRAINER_GEORGE','Use reconciled name and recognize offense as well as healing.',['This is the ENDURANCE ROOM.','Healing buys time. DUBWOOL can turn that time into BODY PRESS power.','Can your team finish the job?'])
a('GeorgeDefeat','TRAINER_GEORGE','A win may come through status, PP, disruption or direct damage.',['We could not outlast your team!'])
a('BerkeIntro','TRAINER_BERKE','No Explosion exists in the actual roster.',['This is the BURST ROOM.','EXPLOUD\'s voice can hit Ghosts. MEGA GLALIE turns Normal attacks into Ice.','Prepare for both sides of the board!'])
a('BerkeDefeat','TRAINER_BERKE','Avoid asserting a specific observed timing solution.',['Your team took the battle!'])
a('BerkePostBattle','TRAINER_BERKE','No Trick Room or Explosion exists; Mega Glalie is a lead rather than final ace.',['A strong pair can attack through different defenses.','The last reserves still matter: STOUTLAND and KANGASKHAN keep the pressure on.'])
a('MaryIntro','TRAINER_MARY','Use reconciled room name; Hustle repair expressly trades accuracy for pressure.',['This is the RETALIATION ROOM.','DRAMPA can gain power after a hard hit. RUFFLET\'s HUSTLE trades accuracy for strength.','Every risk needs a purpose!'])
a('AlexiaIntro','TRAINER_ALEXIA','Use reconciled room name and describe orb strategy accurately.',['This is the STATUS ROOM.','ZANGOOSE and URSARING make their own status a weapon.','Bring a plan for the whole team!'])
a('JodyIntro','TRAINER_JODY','Use reconciled room name without claiming that optimized power teams lack strategy.',['This is the POWER ROOM.','Our LEADER told us to give you everything we have, even if you are his kid.','That is exactly what we will do!'])
(O/'gym-dialogue.json').write_text(json.dumps(entries,indent=2)+'\n')
md=['# Early gym dialogue — exact tactical repairs','','These label-level replacements reconcile the five early gyms with their final teams. They are specifications, not edits to native scripts. World proposal `W-PETALBURG-ROOMS` owns door text, guide directions and neighbor directions; the tactical intro replacements below use its agreed names. All unlisted source labels remain under the world interaction inventory.','', 'Victory text must remain true after any legal winning method, including a clean sweep, status plan, direct coverage or memorized Retry solution. Battle dialogue can preserve personality without inventing observations or absent moves.','']
for e in entries:
 md += [f"## {e['label']}",'',f"**REPAIR** — `{e['trainer']}` · [Snapshot source](../../baseline/source/{e['source']}:{e['line']})",'',e['assessment'],'','Current native text:','','```text',e['current_native'],'```','','Exact proposed native text:','','```text',e['final_native'],'```','',e['acceptance'],'']
(O/'gym-dialogue.md').write_text('\n'.join(md)+'\n');print(len(entries),'dialogue repairs')
